<?php require 'config.php';require 'includes/functions.php';require_login();$s=$pdo->prepare("SELECT * FROM orders WHERE id=? AND user_id=?");$s->execute([(int)($_GET['id']??0),current_user()['id']]);$o=$s->fetch();if(!$o){http_response_code(404);exit('Order not found');}$s=$pdo->prepare("SELECT oi.*,p.name,p.image_url FROM order_items oi JOIN products p ON p.id=oi.product_id WHERE oi.order_id=?");$s->execute([$o['id']]);$items=$s->fetchAll();$title='Order details';require 'includes/header.php';?><div class="page-head"><span class="eyebrow">ORDER #SH<?=$o['id']?></span><h1>Order details</h1><p>Status: <b><?=e($o['status'])?></b> · Payment: <?=e($o['payment_status'])?></p></div><section class="panel"><?php foreach($items as $i):?><div class="cart-row"><img src="<?=e($i['image_url'])?>" alt=""><div class="cart-desc"><b><?=e($i['name'])?></b><small>Qty <?=$i['quantity']?> · <?=money($i['unit_price'])?></small></div></div><?php endforeach;?><h2>Total <?=money($o['total_amount'])?></h2><p>Delivery address: <?=e($o['shipping_address'])?></p></section><?php require 'includes/footer.php';?>